import PQueue from '../source/index.js';

async function testAlreadyAborted() {
  const queue = new PQueue({ concurrency: 1 });

  // Add a long-running task to fill the concurrency slot
  const p1 = queue.add(async () => {
    await new Promise(r => setTimeout(r, 200));
    return 'task1';
  });

  // Create an already-aborted signal
  const controller = new AbortController();
  controller.abort();

  const p2 = queue.add(async () => {
    return 'task2';
  }, { signal: controller.signal });

  try {
    const result = await p2;
    console.log('ERROR: testAlreadyAborted - p2 should have rejected, got:', result);
    process.exit(1);
  } catch (err: any) {
    console.log('OK: testAlreadyAborted - p2 rejected with:', err.message || err);
  }

  console.log('Queue size after adding already-aborted task:', queue.size);
  if (queue.size !== 0) {
    console.log('ERROR: Queue should be empty');
    process.exit(1);
  }

  await p1;
  await queue.onIdle();
}

async function testAbortWhileQueued() {
  const queue = new PQueue({ concurrency: 1 });

  const p1 = queue.add(async () => {
    await new Promise(r => setTimeout(r, 200));
    return 'task1';
  });

  const controller = new AbortController();
  const p2 = queue.add(async () => {
    return 'task2';
  }, { signal: controller.signal });

  // Abort after a short delay
  setTimeout(() => controller.abort(), 50);

  try {
    const result = await p2;
    console.log('ERROR: testAbortWhileQueued - p2 should have rejected, got:', result);
    process.exit(1);
  } catch (err: any) {
    console.log('OK: testAbortWhileQueued - p2 rejected with:', err.message || err);
  }

  await p1;
  await queue.onIdle();
}

async function testAbortWhileRunning() {
  const queue = new PQueue({ concurrency: 1 });

  const controller = new AbortController();

  let taskStarted = false;
  let taskAborted = false;

  const p1 = queue.add(async ({ signal }) => {
    taskStarted = true;
    // Simulate a long task that respects the signal
    try {
      await new Promise((_, reject) => {
        signal?.addEventListener('abort', () => {
          taskAborted = true;
          reject(new DOMException('Aborted', 'AbortError'));
        }, { once: true });
        setTimeout(() => resolve(undefined), 500);
      });
    } catch (err) {
      if (err instanceof DOMException && err.name === 'AbortError') {
        throw err;
      }
      throw err;
    }
  }, { signal: controller.signal });

  // Abort after the task starts running
  setTimeout(() => controller.abort(), 100);

  try {
    const result = await p1;
    console.log('ERROR: testAbortWhileRunning - p1 should have rejected');
    process.exit(1);
  } catch (err: any) {
    console.log('OK: testAbortWhileRunning - p1 rejected with:', err.message || err);
  }

  if (!taskStarted) {
    console.log('ERROR: Task should have started');
    process.exit(1);
  }

  await queue.onIdle();
}

async function main() {
  console.log('=== Edge Case Tests ===');
  await testAlreadyAborted();
  await testAbortWhileQueued();
  console.log('\n=== All edge case tests passed ===');
  process.exit(0);
}

main().catch(err => {
  console.error('Test failed:', err);
  process.exit(1);
});
