import PQueue from '../source/index.js';

async function testMultipleAborts() {
  console.log('Test: Multiple abort signals');
  const queue = new PQueue({ concurrency: 1 });

  // Fill concurrency slot
  const p1 = queue.add(async () => {
    await new Promise(r => setTimeout(r, 300));
  });

  // Add multiple tasks with different abort controllers
  const controller2 = new AbortController();
  const controller3 = new AbortController();
  const controller4 = new AbortController();

  const p2 = queue.add(async () => 'task2', { signal: controller2.signal });
  const p3 = queue.add(async () => 'task3', { signal: controller3.signal });
  const p4 = queue.add(async () => 'task4', { signal: controller4.signal });

  console.log('Queue size before abort:', queue.size);
  if (queue.size !== 3) {
    console.log('ERROR: Expected queue size 3, got', queue.size);
    process.exit(1);
  }

  // Abort task 3
  setTimeout(() => controller3.abort(), 50);

  await new Promise(r => setTimeout(r, 100));
  console.log('Queue size after aborting task 3:', queue.size);
  if (queue.size !== 2) {
    console.log('ERROR: Expected queue size 2, got', queue.size);
    process.exit(1);
  }

  // Verify p3 is rejected
  try {
    await p3;
    console.log('ERROR: p3 should have rejected');
    process.exit(1);
  } catch (err: any) {
    console.log('OK: p3 rejected');
  }

  // Let the rest complete
  controller2.abort();
  controller4.abort();

  await p1;
  try { await p2; } catch {}
  try { await p4; } catch {}

  await queue.onIdle();
  console.log('OK: testMultipleAborts passed');
}

async function testPriorityQueueAbort() {
  console.log('\nTest: Priority queue abort');
  const queue = new PQueue({ concurrency: 1 });

  const p1 = queue.add(async () => {
    await new Promise(r => setTimeout(r, 200));
  }, { priority: 2 });

  const controller2 = new AbortController();
  const controller3 = new AbortController();

  const p2 = queue.add(async () => 'task2', { signal: controller2.signal, priority: 1 });
  const p3 = queue.add(async () => 'task3', { signal: controller3.signal, priority: 0 });

  console.log('Queue size:', queue.size);
  if (queue.size !== 2) {
    console.log('ERROR: Expected queue size 2, got', queue.size);
    process.exit(1);
  }

  // Abort highest priority queued task
  setTimeout(() => controller2.abort(), 50);

  await new Promise(r => setTimeout(r, 100));

  try {
    await p2;
    console.log('ERROR: p2 should have rejected');
    process.exit(1);
  } catch {
    console.log('OK: p2 rejected');
  }

  // p3 should still be queued
  console.log('Queue size after aborting p2:', queue.size);

  // Abort p3 too
  controller3.abort();

  await p1;
  try { await p3; } catch {}

  await queue.onIdle();
  console.log('OK: testPriorityQueueAbort passed');
}

async function main() {
  await testMultipleAborts();
  await testPriorityQueueAbort();
  console.log('\n=== All comprehensive tests passed ===');
  process.exit(0);
}

main().catch(err => {
  console.error('Test failed:', err);
  process.exit(1);
});
